import Link from "next/link";
import type { AnchorHTMLAttributes } from "react";

const DOCUMENT_ROUTES = new Set(["/", "/feed", "/discover", "/walkthrough"]);

type SiteRouteLinkProps = AnchorHTMLAttributes<HTMLAnchorElement> & { href: string };

// These rewrites serve complete HTML documents, not React Server Component payloads.
export function SiteRouteLink({ href, ...props }: SiteRouteLinkProps) {
  const pathname = href.split(/[?#]/, 1)[0];
  if (DOCUMENT_ROUTES.has(pathname)) {
    return <a href={href} {...props} />;
  }
  return <Link href={href} prefetch={false} {...props} />;
}

