for (const destination of ["/feed", "/discover", "/walkthrough"]) {
  test(`shared navigation opens static ${destination} as a document`, async ({ page }) => {
    await page.setViewportSize({ width: 390, height: 844 });
    for (const surface of ["header", "footer"]) {
      await page.goto("/contact");
      const area = page.locator(surface === "header" ? ".mt-refined-header" : ".mt-site-footer");
      if (surface === "header" && destination === "/walkthrough") {
        await area.locator("summary").filter({ hasText: "More" }).click();
      }
      const documentRequest = page.waitForRequest((request) =>
        request.isNavigationRequest() && request.resourceType() === "document" &&
        new URL(request.url()).pathname === destination,
      );
      await area.locator(`a[href="${destination}"]`).click();
      expect((await documentRequest).method()).toBe("GET");
      await expect.poll(() => new URL(page.url()).pathname).toBe(destination);
      await expect(page.locator("body")).not.toBeEmpty();
    }
  });
}
